set -euo pipefail; EXPECTED=d9bbd9be8c975d7ce05590e17631d6092aac49a8; BRANCH=integration/c6-s3-i2c-20260903; GW_SERIAL='40:4C:CA:5D:0A:00'; EMU_SERIAL='40:4C:CA:5D:01:D8'; git fetch origin "$BRANCH"; test "$(git rev-parse origin/$BRANCH)" = "$EXPECTED"; git checkout --detach "$EXPECTED"; test "$(git rev-parse HEAD)" = "$EXPECTED"; echo SOURCE_HEAD=$(git rev-parse HEAD); ZB_OFFSET=0x16e000; ZB_SIZE=0x8000; . ~/esp/esp-idf-v5.5.4/export.sh >/dev/null; GW_PORT=$(python3 - <<'PY'
from serial.tools import list_ports
sn='40:4C:CA:5D:0A:00'
m=[p for p in list_ports.comports() if p.serial_number==sn and p.vid==0x303A]
if len(m)!=1: raise SystemExit(f'GW identity mismatch: {[(p.device,p.serial_number) for p in m]}')
print(m[0].device)
PY
); EMU_PORT=$(python3 - <<'PY'
from serial.tools import list_ports
sn='40:4C:CA:5D:01:D8'
m=[p for p in list_ports.comports() if p.serial_number==sn and p.vid==0x303A]
if len(m)!=1: raise SystemExit(f'EMU identity mismatch: {[(p.device,p.serial_number) for p in m]}')
