); test "$GW_PORT" != "$EMU_PORT"; echo GW_PORT=$GW_PORT GW_SERIAL=$GW_SERIAL; echo EMU_PORT=$EMU_PORT EMU_SERIAL=$EMU_SERIAL; for P in "$GW_PORT" "$EMU_PORT"; do if command -v lsof >/dev/null 2>&1 && lsof "$P" >/tmp/c6_port_holders 2>/dev/null; then echo PORT_BUSY=$P; cat /tmp/c6_port_holders; exit 42; fi; done; echo ERASE_GW_ZB=$GW_PORT:$ZB_OFFSET/$ZB_SIZE; python -m esptool --chip esp32c6 -p "$GW_PORT" --before default_reset --after no_reset erase_region "$ZB_OFFSET" "$ZB_SIZE" >/dev/null; echo ERASE_EMU_ZB=$EMU_PORT:$ZB_OFFSET/$ZB_SIZE; python -m esptool --chip esp32c6 -p "$EMU_PORT" --before default_reset --after no_reset erase_region "$ZB_OFFSET" "$ZB_SIZE" >/dev/null; echo ZB_STORAGE_ERASED_BOTH; python -m esptool --chip esp32c6 -p "$GW_PORT" --before default_reset --after hard_reset chip_id >/dev/null; echo GW_RESET_FOR_FRESH_FORMATION; sleep 1; python -m esptool --chip esp32c6 -p "$EMU_PORT" --before default_reset --after hard_reset chip_id >/dev/null; echo EMU_RESET_FOR_STEERING; sleep 0.2; python3 - <<'PY'
import threading,time,serial
from serial.tools import list_ports
ids={'GW':'40:4C:CA:5D:0A:00','EMU':'40:4C:CA:5D:01:D8'}
ports={}
end=time.time()+10
while time.time()<end:
    ps=list(list_ports.comports())
    ok=True
    for name,sn in ids.items():
        m=[p for p in ps if p.serial_number==sn and p.vid==0x303A]
        if len(m)!=1:
            ok=False
            break
        ports[name]=m[0].device
    if ok and ports['GW']!=ports['EMU']:
        break
    time.sleep(0.15)
else:
    raise SystemExit('failed to resolve both C6 ports after reset')
print('CAPTURE_PORTS='+repr(ports),flush=True)
logs={'GW':[],'EMU':[]}
stop=time.time()+120
def reader(name):
    with serial.Serial(ports[name],115200,timeout=0.1) as s:
        while time.time()<stop:
            b=s.readline()
            if b:
                t=b.decode('utf-8','replace').rstrip('\r\n')
                logs[name].append(t)
                print(f'{name}: {t}',flush=True)
threads=[threading.Thread(target=reader,args=(n,),daemon=True) for n in ('GW','EMU')]
for t in threads:
    t.start()
for t in threads:
    t.join()
g='\n'.join(logs['GW'])
e='\n'.join(logs['EMU'])
print('GW_LINES='+str(len(logs['GW'])))
print('EMU_LINES='+str(len(logs['EMU'])))
print('EMU_ABORT='+str('abort() was called' in e or 'Guru Meditation' in e))
keys={
    'GW_NETWORK_FORMED':['network formed','formed'],
    'GW_PERMIT_JOIN':['permit join','permit_join'],
    'GW_ANNOUNCE':['announce','device_announce'],
    'GW_IAS':['0x0500','ias zone','ias'],
    'GW_ZONETYPE':['0x0015','zonetype','zone type'],
    'GW_CONTACT':['contact_open','contact open'],
    'EMU_FACTORY_NEW':['factory_new=1'],
    'EMU_STEERING':['network steering status='],
    'EMU_REPORT':['report request ep=1 cluster=0x0500 attr=0x0002']
}
for label,terms in keys.items():
    text=g if label.startswith('GW_') else e
    print(label+'_HITS='+str(sum(text.lower().count(x.lower()) for x in terms)))
print('=== GW RELEVANT ===')
for line in logs['GW']:
    l=line.lower()
    if any(x in l for x in ['zigbee','network','permit','announce','device','descriptor','0x0500','0x0015','ias','zone','contact','report']):
        print(line)
print('=== EMU RELEVANT ===')
for line in logs['EMU']:
    l=line.lower()
    if any(x in l for x in ['zigbee','factory_new','steering','join','ias','zone','tick','report','abort']):
        print(line)
PY
